/// Get BSD syscall name by number
pub fn bsd_syscall_name(num: u32) -> Option<&'static str> {
    BSD_SYSCALL_TABLE
        .iter()
        .find(|e| e.number == num)
        .map(|e| e.name)
}

/// Get Mach trap name by number
pub fn mach_trap_name(num: i32) -> Option<&'static str> {
    MACH_TRAP_TABLE
        .iter()
        .find(|e| e.number == num)
        .map(|e| e.name)
}
